const p = $input.first().json.body;
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const r = p.report;
const colors = {critical:'#b3261e', high:'#e07b1a', medium:'#c9a227', low:'#4f7a3a'};
const c = colors[r.priority_label] || '#4f7a3a';
const evt = p.event === 'report.resolved' ? '✅ Résolu' : (r.priority_label === 'critical' || r.danger_to_people ? '🔴 URGENT' : 'Nouveau');
const subject = `[Eco-Route] ${evt} – ${esc(r.category_label)} – ${esc(r.zone)}`;
const html = `
<div style="font-family:Arial,sans-serif;max-width:560px">
  <div style="background:#567d3a;color:#fff;padding:16px 20px;border-radius:10px 10px 0 0">
    <h2 style="margin:0">Sfax Eco-Route</h2><div>${evt} signalement</div>
  </div>
  <div style="border:1px solid #ddd;border-top:0;padding:20px;border-radius:0 0 10px 10px">
    <p style="margin:0 0 8px"><span style="background:${c};color:#fff;padding:3px 10px;border-radius:12px;font-weight:bold">${r.priority_label.toUpperCase()} · ${r.priority_score}/100</span>&nbsp; SLA ${r.sla_hours} h</p>
    ${r.danger_to_people ? '<p style="background:#fde7e5;color:#b3261e;padding:8px 12px;border-radius:8px;font-weight:bold">⚠️ Danger pour les personnes signalé</p>' : ''}
    <h3 style="margin:12px 0 4px">${esc(r.category_label)}</h3>
    <p style="margin:0;color:#555">${esc(r.road_name)} — ${esc(r.zone)}</p>
    <p style="white-space:pre-wrap">${esc(r.description)}</p>
    ${r.ai_summary ? `<p style="background:#f3f6ef;padding:10px;border-radius:8px"><b>Résumé IA :</b> ${esc(r.ai_summary)}</p>` : ''}
    <table style="font-size:14px">
      <tr><td><b>Service responsable</b></td><td>${esc(r.service)}</td></tr>
      <tr><td><b>Criticité de la route</b></td><td>${Math.round(r.road_criticality*100)} %</td></tr>
      <tr><td><b>Urgence citoyen</b></td><td>${r.citizen_urgency}/100</td></tr>
      <tr><td><b>Référence</b></td><td>${esc(r.id)}</td></tr>
    </table>
    <p><a href="${r.maps_url}" style="background:#567d3a;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none">Voir sur la carte</a></p>
  </div>
</div>`;
return [{ json: { to: p.notify_email, subject, html, priority: r.priority_label, event: p.event, report: r } }];
